const open=new Promise((resolve,reject)=>{const req=indexedDB.open('mingjian',1);req.onupgradeneeded=()=>req.result.createObjectStore('records',{keyPath:'id'});req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});
export async function loadRecords(){const db=await open;const records=await new Promise((resolve,reject)=>{const req=db.transaction('records').objectStore('records').getAll();req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});return records.sort((a,b)=>b.createdAt.localeCompare(a.createdAt));}
export async function saveRecord(record){const db=await open;await new Promise((resolve,reject)=>{const tx=db.transaction('records','readwrite');tx.objectStore('records').put(structuredClone(record));tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);});}
export async function clearRecords(){const db=await open;await new Promise((resolve,reject)=>{const tx=db.transaction('records','readwrite');tx.objectStore('records').clear();tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});localStorage.removeItem('mingjian-reviews-v1');}
